-- Separate schema keeps application data out of the Supabase public REST schema.
CREATE SCHEMA IF NOT EXISTS mirror;
CREATE TABLE mirror.tenants(id uuid PRIMARY KEY DEFAULT gen_random_uuid(), name text NOT NULL CHECK(length(name) BETWEEN 2 AND 120), status text NOT NULL DEFAULT 'ACTIVE' CHECK(status IN ('ACTIVE','SUSPENDED')), created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE mirror.branches(id uuid PRIMARY KEY DEFAULT gen_random_uuid(), tenant_id uuid NOT NULL REFERENCES mirror.tenants(id), name text NOT NULL, address text NOT NULL DEFAULT '', status text NOT NULL DEFAULT 'ACTIVE', UNIQUE(id,tenant_id));
CREATE TABLE mirror.users(id uuid PRIMARY KEY DEFAULT gen_random_uuid(), tenant_id uuid REFERENCES mirror.tenants(id), branch_id uuid, email text NOT NULL UNIQUE, password_hash text NOT NULL, role text NOT NULL CHECK(role IN ('SUPER_ADMIN','BRAND_ADMIN','STORE_ADMIN','STAFF')), status text NOT NULL DEFAULT 'ACTIVE' CHECK(status IN ('ACTIVE','SUSPENDED','PENDING')), created_at timestamptz NOT NULL DEFAULT now(), FOREIGN KEY(branch_id,tenant_id) REFERENCES mirror.branches(id,tenant_id), CHECK((role='SUPER_ADMIN' AND tenant_id IS NULL AND branch_id IS NULL) OR (role='BRAND_ADMIN' AND tenant_id IS NOT NULL AND branch_id IS NULL) OR (role IN ('STORE_ADMIN','STAFF') AND tenant_id IS NOT NULL AND branch_id IS NOT NULL)));
CREATE TABLE mirror.sessions(id uuid PRIMARY KEY, user_id uuid NOT NULL REFERENCES mirror.users(id), refresh_hash text NOT NULL UNIQUE, expires_at timestamptz NOT NULL, revoked_at timestamptz, created_at timestamptz NOT NULL DEFAULT now());
CREATE INDEX ON mirror.sessions(user_id);
CREATE TABLE mirror.plans(id text PRIMARY KEY, name text NOT NULL, price_cents integer NOT NULL CHECK(price_cents>=0), branch_limit integer NOT NULL CHECK(branch_limit>0), device_limit integer NOT NULL CHECK(device_limit>0), monthly_tryons integer NOT NULL CHECK(monthly_tryons>=0));
INSERT INTO mirror.plans VALUES('starter','Starter',9900,1,2,400),('growth','Growth',24900,5,12,1000),('studio','Studio',69900,20,50,3000);
CREATE TABLE mirror.subscriptions(tenant_id uuid PRIMARY KEY REFERENCES mirror.tenants(id), plan_id text NOT NULL REFERENCES mirror.plans(id), status text NOT NULL DEFAULT 'ACTIVE' CHECK(status IN ('ACTIVE','SUSPENDED','EXPIRED')), period_start timestamptz NOT NULL DEFAULT now(), period_end timestamptz NOT NULL DEFAULT now()+interval '1 month', expires_at timestamptz NOT NULL DEFAULT now()+interval '1 month', used integer NOT NULL DEFAULT 0 CHECK(used>=0), extra_credits integer NOT NULL DEFAULT 0 CHECK(extra_credits>=0));
CREATE TABLE mirror.products(id uuid PRIMARY KEY DEFAULT gen_random_uuid(), tenant_id uuid NOT NULL REFERENCES mirror.tenants(id), name text NOT NULL CHECK(length(name) BETWEEN 1 AND 160), description text NOT NULL DEFAULT '', category text NOT NULL, price_cents integer NOT NULL CHECK(price_cents>=0), original_price_cents integer CHECK(original_price_cents>price_cents), sku text NOT NULL, barcode text NOT NULL DEFAULT '', status text NOT NULL DEFAULT 'Draft' CHECK(status IN ('Published','Draft','Archived','Blocked')), created_at timestamptz NOT NULL DEFAULT now(), UNIQUE(id,tenant_id), UNIQUE(tenant_id,sku));
CREATE TABLE mirror.variants(id uuid PRIMARY KEY DEFAULT gen_random_uuid(), tenant_id uuid NOT NULL, product_id uuid NOT NULL, size text NOT NULL, color text NOT NULL, sku text NOT NULL, barcode text NOT NULL DEFAULT '', active boolean NOT NULL DEFAULT true, FOREIGN KEY(product_id,tenant_id) REFERENCES mirror.products(id,tenant_id), UNIQUE(id,tenant_id), UNIQUE(id,product_id,tenant_id), UNIQUE(tenant_id,sku));
CREATE TABLE mirror.inventory(tenant_id uuid NOT NULL, branch_id uuid NOT NULL, variant_id uuid NOT NULL, quantity integer NOT NULL DEFAULT 0 CHECK(quantity>=0), blocked integer NOT NULL DEFAULT 0 CHECK(blocked>=0 AND blocked<=quantity), PRIMARY KEY(branch_id,variant_id), FOREIGN KEY(branch_id,tenant_id) REFERENCES mirror.branches(id,tenant_id), FOREIGN KEY(variant_id,tenant_id) REFERENCES mirror.variants(id,tenant_id));
CREATE TABLE mirror.devices(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),tenant_id uuid NOT NULL,branch_id uuid NOT NULL,name text NOT NULL,configuration jsonb NOT NULL DEFAULT '{}',status text NOT NULL DEFAULT 'INACTIVE',last_seen timestamptz,FOREIGN KEY(branch_id,tenant_id) REFERENCES mirror.branches(id,tenant_id));
CREATE TABLE mirror.images(id uuid PRIMARY KEY,tenant_id uuid NOT NULL REFERENCES mirror.tenants(id),owner_id uuid NOT NULL REFERENCES mirror.users(id),product_id uuid,bucket text NOT NULL,object_path text NOT NULL UNIQUE,mime_type text NOT NULL,size_bytes integer NOT NULL CHECK(size_bytes>0),width integer NOT NULL,height integer NOT NULL,approved boolean NOT NULL DEFAULT false,kind text NOT NULL CHECK(kind IN ('product','tryon')),expires_at timestamptz,created_at timestamptz NOT NULL DEFAULT now(),FOREIGN KEY(product_id,tenant_id) REFERENCES mirror.products(id,tenant_id),CHECK((kind='product' AND approved AND product_id IS NOT NULL AND expires_at IS NULL) OR (kind='tryon' AND NOT approved AND product_id IS NULL AND expires_at IS NOT NULL)));
CREATE INDEX ON mirror.images(product_id);
CREATE INDEX ON mirror.images(expires_at) WHERE expires_at IS NOT NULL;
CREATE TABLE mirror.storage_jobs(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),bucket text NOT NULL,object_path text NOT NULL,run_after timestamptz NOT NULL DEFAULT now(),attempts integer NOT NULL DEFAULT 0,UNIQUE(bucket,object_path));
CREATE TABLE mirror.tryon_sessions(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),tenant_id uuid NOT NULL,user_id uuid NOT NULL REFERENCES mirror.users(id),branch_id uuid NOT NULL,product_id uuid NOT NULL,variant_id uuid NOT NULL,idempotency_key text NOT NULL,status text NOT NULL CHECK(status IN ('PENDING','SUCCEEDED','FAILED')),consent_at timestamptz NOT NULL,created_at timestamptz NOT NULL DEFAULT now(),FOREIGN KEY(branch_id,tenant_id) REFERENCES mirror.branches(id,tenant_id),FOREIGN KEY(variant_id,product_id,tenant_id) REFERENCES mirror.variants(id,product_id,tenant_id),UNIQUE(tenant_id,idempotency_key));
CREATE TABLE mirror.ai_usage(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),session_id uuid NOT NULL UNIQUE REFERENCES mirror.tryon_sessions(id),provider text NOT NULL,provider_request_id text NOT NULL,actual_cost_micros bigint CHECK(actual_cost_micros>=0),created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE mirror.credit_ledger(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),tenant_id uuid NOT NULL REFERENCES mirror.tenants(id),reference text NOT NULL,delta integer NOT NULL CHECK(delta<>0),created_at timestamptz NOT NULL DEFAULT now(),UNIQUE(tenant_id,reference));
CREATE TABLE mirror.carts(user_id uuid NOT NULL REFERENCES mirror.users(id),tenant_id uuid NOT NULL,product_id uuid NOT NULL,variant_id uuid NOT NULL,qty integer NOT NULL CHECK(qty BETWEEN 1 AND 100),PRIMARY KEY(user_id,variant_id),FOREIGN KEY(variant_id,product_id,tenant_id) REFERENCES mirror.variants(id,product_id,tenant_id));
CREATE TABLE mirror.orders(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),tenant_id uuid NOT NULL,user_id uuid NOT NULL REFERENCES mirror.users(id),branch_id uuid NOT NULL,status text NOT NULL DEFAULT 'SENT_TO_CASHIER',created_at timestamptz NOT NULL DEFAULT now(),FOREIGN KEY(branch_id,tenant_id) REFERENCES mirror.branches(id,tenant_id),UNIQUE(id,tenant_id));
CREATE TABLE mirror.order_items(order_id uuid NOT NULL,tenant_id uuid NOT NULL,product_id uuid NOT NULL,variant_id uuid NOT NULL,qty integer NOT NULL CHECK(qty BETWEEN 1 AND 100),price_cents integer NOT NULL CHECK(price_cents>=0),PRIMARY KEY(order_id,variant_id),FOREIGN KEY(order_id,tenant_id) REFERENCES mirror.orders(id,tenant_id),FOREIGN KEY(variant_id,product_id,tenant_id) REFERENCES mirror.variants(id,product_id,tenant_id));
CREATE TABLE mirror.notifications(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),tenant_id uuid NOT NULL REFERENCES mirror.tenants(id),branch_id uuid,title text NOT NULL,read_at timestamptz,created_at timestamptz NOT NULL DEFAULT now(),FOREIGN KEY(branch_id,tenant_id) REFERENCES mirror.branches(id,tenant_id));
CREATE TABLE mirror.audit_logs(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),tenant_id uuid REFERENCES mirror.tenants(id),actor_id uuid REFERENCES mirror.users(id),action text NOT NULL,details jsonb NOT NULL DEFAULT '{}',created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE mirror.applications(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),payload jsonb NOT NULL,status text NOT NULL DEFAULT 'NEW',created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE mirror.application_events(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),application_id uuid NOT NULL REFERENCES mirror.applications(id),event_type text NOT NULL,created_at timestamptz NOT NULL DEFAULT now());
CREATE INDEX ON mirror.products(tenant_id,category);
CREATE INDEX ON mirror.branches(tenant_id);
CREATE INDEX ON mirror.devices(tenant_id,branch_id);
CREATE INDEX ON mirror.orders(tenant_id,branch_id,created_at);
CREATE INDEX ON mirror.tryon_sessions(tenant_id,branch_id,created_at);
CREATE INDEX ON mirror.audit_logs(tenant_id,created_at);
-- No grants to Supabase browser roles. Defense in depth if schema is later exposed.
DO $$ DECLARE t record; BEGIN FOR t IN SELECT tablename FROM pg_tables WHERE schemaname='mirror' LOOP EXECUTE format('ALTER TABLE mirror.%I ENABLE ROW LEVEL SECURITY',t.tablename); END LOOP; END $$;
REVOKE ALL ON SCHEMA mirror FROM PUBLIC;
